-- Isolated Feature 32 Test Center history. It does not own or alter product routing.
CREATE OR REPLACE FUNCTION execution_quality_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'execution quality history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS execution_quality_runs(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS execution_quality_decisions(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,artifact_hash),FOREIGN KEY(operator_test_id,run_hash) REFERENCES execution_quality_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS execution_quality_request_claims(operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,run_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key),FOREIGN KEY(operator_test_id,run_hash) REFERENCES execution_quality_runs(operator_test_id,run_hash));
DO $$ DECLARE tab text; BEGIN FOREACH tab IN ARRAY ARRAY['execution_quality_runs','execution_quality_decisions','execution_quality_request_claims'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS execution_quality_immutable ON %I',tab); EXECUTE format('CREATE TRIGGER execution_quality_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION execution_quality_append_only()',tab); END LOOP; END $$;
CREATE INDEX IF NOT EXISTS execution_quality_run_scope_idx ON execution_quality_runs(operator_test_id,created_at);
